<?php

namespace App\Services;

use Illuminate\Support\Facades\Http;
use App\Support\PterohubPterodactylConfig as ApiConfig;
use RuntimeException;

class PterodactylCatalogApi
{
    private function request(string $path, array $params = []): array
    {
        $base = ApiConfig::url();
        $key = ApiConfig::apiKey();
        if (!str_starts_with($base, 'https://') || !$key) {
            throw new RuntimeException('Configure HTTPS panel URL and Application API key in Settings > Pterodactyl');
        }
        // Only static or numeric API paths are generated by this service.
        $res = Http::withToken($key)
            ->accept('application/vnd.pterodactyl.v1+json')
            ->timeout(20)->retry(2, 600)
            ->get($base . '/api/application/' . ltrim($path, '/'), $params);
        if (!$res->successful()) {
            throw new RuntimeException('Pterodactyl GET ' . $path . ' failed (HTTP ' . $res->status() . ')');
        }
        return $res->json() ?? [];
    }

    public function pages(string $path, array $params = []): array
    {
        $results = [];
        for ($page = 1; $page <= 100; $page++) {
            $response = $this->request($path, $params + ['page' => $page, 'per_page' => 100]);
            foreach (($response['data'] ?? []) as $row) {
                if (isset($row['attributes']) && is_array($row['attributes'])) {
                    $results[] = $row['attributes'];
                }
            }
            $pagination = $response['meta']['pagination'] ?? null;
            if (!$pagination || $page >= (int) ($pagination['total_pages'] ?? 1)) {
                return $results;
            }
        }
        throw new RuntimeException('API returned more than 100 pages: limit reached for safety');
    }

    public function eggs(): array
    {
        // Pterodactyl v2 supports a global eggs endpoint; older variants use nests.
        try {
            return $this->pages('eggs', ['include' => 'variables']);
        } catch (RuntimeException $ex) {
            if (!str_contains($ex->getMessage(), 'HTTP 404')) {
                throw $ex;
            }
        }
        $eggs = [];
        foreach ($this->pages('nests') as $nest) {
            if (!isset($nest['id'])) continue;
            foreach ($this->pages('nests/' . (int) $nest['id'] . '/eggs', ['include' => 'variables']) as $egg) {
                $eggs[] = $egg;
            }
        }
        return $eggs;
    }

    public function nodes(): array
    {
        return $this->pages('nodes', ['include' => 'location']);
    }
}
